// One request per band. The old version fired a single static GET and could
// never pull a trade tape per market.
const cfg = $('Config').first().json;
const template = String(cfg.trades_url || '');
if (!template.includes('{market}')) {
  throw new Error('trades_url must contain the placeholder {market}. Got: ' + template);
}
const limit = String(Number(cfg.trades_per_band || 100) || 100);

const bands = $('Load bands').all().map(i => i.json).flat();
const cap = Number(cfg.max_bands_per_run || 0) || 0;

// One request per distinct condition_id - bands of the same market share it,
// so requesting per band would fetch the same tape many times over.
const seen = new Set();
const out = [];
for (const b of bands) {
  const cid = b && b.condition_id;
  if (!cid || seen.has(String(cid))) continue;
  seen.add(String(cid));
  out.push({ json: {
    condition_id: cid,
    trades_url: template.replace('{market}', encodeURIComponent(cid))
                        .replace('{limit}', limit),
  }});
  if (cap && out.length >= cap) break;
}
if (out.length === 0) {
  throw new Error('No bands with a condition_id came back from Supabase. ' +
                  'Check that bands.condition_id is populated.');
}
return out;

// A CAP THAT DOES NOT TRUST THE ENDPOINT.
//
// trades_url carries &limit={limit}, and P0.2 learned this the hard way:
// Polymarket IGNORES query parameters it does not recognise rather than
// rejecting them. ?limit=40 on the events feed returned 2160 events and 26 MB,
// and n8n went offline holding it. If limit is ignored here too, a busy market
// hands back its entire trade tape and this node maps every row of it.
//
// So the cap is enforced HERE, on what actually arrived, rather than asked for
// in a URL and hoped for. max_rows is in Config.
const _cfg     = $('Config').first().json;
const MAX_ROWS = Math.max(1, Number(_cfg.max_rows || 5000));
let _capped    = false;

// Build trades_observed rows.
//
// CONFIRMED against the live database (sql/ad4_99_verify.sql section 7):
//   trade_id bigint, band_id uuid, condition_id text, traded_at timestamptz,
//   price numeric, size numeric, side text, proxy_wallet text,
//   ingested_at timestamptz, city_key text, token_id text
//
// THE TIMESTAMP COLUMN IS `traded_at`. An earlier version wrote
// `observed_at` - a column that exists but is NULL on every one of the
// 122,373 existing rows, which is exactly why every band reported $0 traded
// volume while the data sat right there.
//
// band_id is what makes BAND-level volume possible. Without it only
// city-level volume works and every band still reads thin.
const bands = $('Load bands').all().map(i => i.json).flat();

// token id -> band, so a trade on either leg attributes home.
const byToken = new Map();
for (const b of bands) {
  if (b.token_yes) byToken.set(String(b.token_yes), b);
  if (b.token_no)  byToken.set(String(b.token_no),  b);
}
// condition_id -> the bands under it. Used ONLY when the payload names no
// token at all, and only when that condition has exactly ONE band - so a
// trade is never attributed to an arbitrary band of a multi-band market.
const byCondition = new Map();
for (const b of bands) {
  if (!b.condition_id) continue;
  const k = String(b.condition_id);
  if (!byCondition.has(k)) byCondition.set(k, []);
  byCondition.get(k).push(b);
}

const requests = $('Build request list').all().map(i => i.json);
const responses = $input.all().map(i => i.json);

const ingestedAt = new Date().toISOString();
const rows = [];
let unmatched = 0, failed = 0;

function toIso(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number' || /^\d+$/.test(String(v))) {
    const num = Number(v);
    // seconds vs milliseconds: anything below ~1e12 is seconds
    return new Date(num < 1e12 ? num * 1000 : num).toISOString();
  }
  const d = new Date(v);
  return isNaN(d.getTime()) ? null : d.toISOString();
}

for (let i = 0; i < requests.length; i++) {
  const req = requests[i];
  const res = responses[i];
  if (!res || res.error) { failed++; continue; }

  // the tape may come back as an array, or wrapped in {data|trades|history}
  const tape = Array.isArray(res) ? res
             : (res.data || res.trades || res.history || []);
  if (!Array.isArray(tape)) { failed++; continue; }

  for (const t of tape) {
    if (!t) continue;
    const token = String(t.asset_id ?? t.token_id ?? t.tokenId ?? '');
    // A NAMED token that we do not recognise is unmatched - never guess.
    // Falling back to the condition here would credit one band's volume to
    // another band of the same market, which is worse than dropping it.
    let band = token ? byToken.get(token) : null;
    if (!band && !token) {
      const candidates = byCondition.get(String(req.condition_id)) || [];
      if (candidates.length === 1) band = candidates[0];
    }
    if (!band) { unmatched++; continue; }

    const price = Number(t.price);
    const size = Number(t.size ?? t.amount ?? t.shares);
    if (!Number.isFinite(price) || !Number.isFinite(size) || size <= 0) continue;
    if (price <= 0 || price >= 1) continue;   // outside a probability

    const tradedAt = toIso(t.timestamp ?? t.match_time ?? t.traded_at ?? t.time);
    if (!tradedAt) continue;                  // no time = useless for volume

    if (rows.length >= MAX_ROWS) { _capped = true; break; }
    rows.push({
      band_id: band.band_id,
      condition_id: req.condition_id,
      // THE CITY, WHICH THIS HAS NEVER WRITTEN. `bands` has no city_key -
      // it is on `markets` - so `band.city_key` was undefined on every row
      // and every trade landed with a null city. v_city_volume is
      // `where city_key is not null group by city_key`, so it returned ZERO
      // ROWS: the Board, the Globe, City Clusters and the Goals feasibility
      // read all showed $0 of city volume and none of them could tell that
      // apart from a quiet market. Load bands now embeds markets(city_key).
      city_key: band.city_key ?? band.markets?.city_key ?? null,
      token_id: token || null,
      side: t.side ?? t.taker_side ?? null,
      price,
      size,
      traded_at: tradedAt,                    // THE real column
      proxy_wallet: t.proxyWallet ?? t.proxy_wallet ?? t.maker ?? null,
      ingested_at: ingestedAt,                // when WE saw it, kept separate
    });
  }
}

const volumeUsd = rows.reduce((s, r) => s + r.price * r.size, 0);
return [{ json: {
  rows, n: rows.length, unmatched, failed,
  requested: requests.length,
  capped: _capped, max_rows: MAX_ROWS,
  volume_usd: Number(volumeUsd.toFixed(2)),
} }];

const p = $('Map trades to bands').first().json;
if (p.n === 0) {
  throw new Error(
    `Parsed 0 trades out of ${p.requested} requests ` +
    `(${p.failed} failed, ${p.unmatched} unmatched tokens). Nothing was ` +
    `written. Most likely the Polymarket trades endpoint in Config is wrong ` +
    `for your setup, or its response shape is not an array of ` +
    `{price,size,timestamp}. Open your original P0.4 and copy its URL across.`);
}
return [{ json: p }];

const AD4_WRITE_NODES = ["Insert trades", "Refresh volume rollups"];
// AD4-WRITE-GUARD
// DID THE DATABASE ACTUALLY TAKE IT?
//
// Every write node in this workflow carries onError=continueRegularOutput so
// that one bad row cannot kill a run. The cost of that is a REFUSED write
// walks straight past it and arrives here looking healthy - which is how a
// workflow reports "ok, 0 rows" for days while the data quietly stops moving.
//
// With neverError on, a refusal arrives as the PostgREST error body instead of
// an exception, so it can be read and named. That is what this does.
function ad4WriteError(node) {
  let items;
  try { items = $(node).all(); } catch (e) { return null; }
  for (const it of items || []) {
    const b = it && it.json;
    if (!b || typeof b !== 'object') continue;
    if (b.error && !b.code) return { node, code: null, message: String(b.error).slice(0, 300) };
    if (b.code || b.message) {
      return { node, code: b.code ?? null, message: b.message ?? '',
               details: b.details ?? null, hint: b.hint ?? null };
    }
  }
  return null;
}

for (const node of AD4_WRITE_NODES) {
  const e = ad4WriteError(node);
  if (!e) continue;
  // 42501 is the one worth naming, because the cause is never in the code.
  if (String(e.code) === '42501' || /permission denied/i.test(e.message)) {
    throw new Error(
      `Supabase REFUSED the write at "${e.node}": ${e.message} (${e.code}). The key was ` +
      `already checked at "Run now?" and claims to be the service key, so this is the ` +
      `DATABASE side: service_role has no INSERT on that table. Run sql/ad4_38_grants.sql ` +
      `in the Supabase SQL editor - it grants the write path back, then prints one row per ` +
      `ingest table saying whether the service key can write it. Nothing was written.`);
  }
  if (String(e.code) === '42P01') {
    throw new Error(
      `Supabase has no such table for "${e.node}": ${e.message}. The sql/ files that create ` +
      `it have not been run - sql/ad4_98_ui_health.sql names which file owns which table. ` +
      `Nothing was written.`);
  }
  throw new Error(
    `Supabase refused the write at "${e.node}": ${e.message}` +
    (e.code ? ` (${e.code})` : '') + (e.details ? ` - ${e.details}` : '') +
    (e.hint ? ` Hint: ${e.hint}` : '') + ' Nothing was written.');
}

const p = $('Map trades to bands').first().json;
const d = $('Refresh volume rollups').first().json || {};
const rows = p.n || 0;
const _m = $('Map trades to bands').first().json;
const _capNote = _m.capped ? ` Stopped at the ${_m.max_rows}-row cap - raise max_rows in Config if that is short.` : '';
const summary =
  `AD4 P0.4: ${rows} trades ($${p.volume_usd}) written from ${p.requested} markets, ` +
  `${p.unmatched} unmatched tokens. ` +
  `Rollups: ${d.city_day_volume_rows ?? '?'} city-day, ${d.band_day_volume_rows ?? '?'} band-day.`;
const status = rows > 0 ? 'ok' : 'attention';
const detail = { volume_usd: p.volume_usd, unmatched: p.unmatched,
                 failed: p.failed, requested: p.requested, rollups: d };
return [{ json: {
  summary: summary + _capNote, status, rows,
  log: { p_job: 'P0.4_trade_history', p_status: status, p_rows: rows,
         p_detail: { ...detail, summary, trigger: $execution.mode, execution_id: $execution.id } },
} }];

// AD4-KEY-CHECK
// THE KEY IS NOT IN THIS FILE ANY MORE, AND THAT IS THE POINT.
//
// Every Supabase node in this workflow authenticates with an n8n SUPABASE
// CREDENTIAL rather than a key pasted into the Config node. That is one place
// to set it instead of twelve, it is encrypted at rest in n8n, and exporting
// this workflow can no longer leak it - the old shape had the service key
// sitting in plain text inside a JSON file that gets emailed around.
//
// SET IT UP ONCE, BEFORE IMPORTING ANYTHING:
//   n8n -> Credentials -> New -> Supabase API
//     Name         AD4 Supabase        <- this name exactly
//     Host         https://<your-project-ref>.supabase.co
//     Service Role the SERVICE ROLE key (Project Settings -> API keys)
//
// The name matters because every Supabase node in every AD4 workflow is
// already bound to a credential called AD4 Supabase. Create it first and
// n8n links all of them on import - nothing to pick node by node. Import
// first and the nodes come in unbound, and you pick the credential on each
// one by hand; it works, it is just ~57 dropdowns instead of zero.
//
// The credential sends `apikey` and `Authorization: Bearer` itself, which is
// exactly what these nodes used to set by hand.
//
// WHAT STILL CHECKS THE KEY. This node can no longer read it - a credential
// is not visible to an expression, by design. Two things downstream do:
//
//   the schedule gate, immediately below. sql/ad4_38 revokes should_run from
//   anon, so a credential holding the publishable key is refused HERE, two
//   nodes in, before a single row is fetched.
//
//   the write guard in the Summary node, which names any refusal the
//   database gives and refuses to report success on a run that wrote nothing.
//
// supabase_url stays in Config because an expression has to build the request
// URL and cannot read the credential's host. It is not a secret.
{
  const cfg = $('Config').first().json ?? {};
  const url = String(cfg.supabase_url ?? '').trim();
  if (!url) {
    throw new Error(
      'Config -> supabase_url is empty. Set it to exactly ' +
      'https://<your-project-ref>.supabase.co - no trailing slash and no /rest/v1, ' +
      'which every node below appends itself. The KEY does not go here: it belongs in ' +
      'the n8n Supabase credential (Credentials -> New -> Supabase API), which is ' +
      'where the nodes now read it from.');
  }
  if (!/^https:\/\//.test(url) || /\/rest\b/.test(url) || /\/$/.test(url)) {
    throw new Error(
      `Config -> supabase_url is "${url}", which is not the shape every node below ` +
      'expects: https://<your-project-ref>.supabase.co, no trailing slash, no /rest/v1. ' +
      'Nothing was fetched and nothing was written.');
  }
}

// AN ENDPOINT THIS FILE CANNOT KNOW.
//
// P0.2-P0.5 are RECONSTRUCTIONS. The Supabase half is grounded in the real
// schema and is safe; the Polymarket half never was. These files used to ship
// with a plausible-looking URL already filled in, which is worse than shipping
// none: it reads as authoritative, so nobody changes it, and the run dies four
// nodes later with a message about response shapes. That is exactly how this
// wasted an afternoon.
//
// So the field ships EMPTY and the run stops here - before any HTTP call,
// before any database read - saying where the real value is.
{
  const cfg = $('Config').first().json ?? {};
  const missing = Object.keys(cfg)
    .filter((k) => k.endsWith('_url') && k !== 'supabase_url')
    .filter((k) => !String(cfg[k] ?? '').trim());
  if (missing.length) {
    throw new Error(
      `Config.${missing.join(' and Config.')} is empty, and this file cannot fill it in. ` +
      `Open your OWN working P0.2-P0.5 in n8n, click its Polymarket HTTP node, copy the URL ` +
      `from it, and paste it here. Those workflows are what put 841 markets and 122,000 trades ` +
      `in this database - they are the authority on the endpoint, not this reconstruction. ` +
      `Nothing was fetched and nothing was written.`);
  }
}

// Ask the database whether this run should do anything.
//
// n8n cannot be told from outside not to FIRE a schedule trigger, so the saving
// is here: returning no items stops every node below, and the execution ends
// having done two trivial requests instead of the whole job.
//
// settings.workflow_schedules owns the answer (sql/ad4_20_schedules.sql) and
// the Workflows page edits it. A manual or webhook run always proceeds - a Run
// button that obeyed the cadence would be a Run button that does nothing.
const d = $('Check schedule').first().json ?? {};
const decision = Array.isArray(d) ? d[0] : d;

// A PERMISSION ERROR IS NOT AN UNAVAILABLE GATE. 42501 here means the key
// cannot even call should_run, and a key that cannot do that cannot write
// either - so stop, rather than failing open into a run that writes nothing.
//
// THIS NODE CANNOT CHECK THE KEY ITSELF ANY MORE - it is in the credential,
// which an expression cannot read. So a refusal here is one of two things and
// both stop the run: the credential holds the anon/publishable key rather than
// the service role key, or service_role has not been granted what it needs.
// Either way every write below would be refused the same way, so there is
// nothing to gain by going on. ad4_38's output tells you which it was.
//
// ad4_38 revokes should_run from anon for this reason: it was granted so the
// Workflows page could preview a cadence, that page reads v_execution_budget
// instead, and the grant only let a bad key through the gate.
if (decision && (String(decision.code) === '42501' ||
                 /permission denied/i.test(String(decision.message || '')))) {
  throw new Error(
    `Supabase refused should_run: ${decision.message} (${decision.code}). Every write below ` +
    `would be refused the same way, so nothing was fetched and nothing was written. Two ` +
    `things cause this and the workflow cannot tell them apart, because the key now lives ` +
    `in the n8n credential where an expression cannot read it. (1) THE KEY: open n8n -> ` +
    `Credentials -> the Supabase account these nodes use and check Service Role Secret ` +
    `holds the SERVICE ROLE key (Supabase -> Project Settings -> API -> service_role, or a ` +
    `key beginning sb_secret_) - an anon key gets exactly this error, because anon is ` +
    `granted SELECT and nothing else. NEVER put the service key anywhere starting ` +
    `NEXT_PUBLIC_. (2) THE DATABASE: service_role has not been granted what it needs. Run ` +
    `sql/ad4_38_grants.sql in the Supabase SQL editor - it grants the write path back and ` +
    `then prints one row per ingest table saying whether the service key can write it, ` +
    `which also tells you which of the two it was.`);
}

// A gate that fails closed would silently disable every workflow the first
// time the settings row is missing or the RPC is absent. Fail OPEN: an
// unreachable gate means run, and say so in the log.
if (decision === null || decision === undefined || decision.run === undefined) {
  console.log('schedule gate unavailable - running anyway');
  return $input.all();
}

if (decision.run === false) {
  // Recorded, so a skipped run is visible on the Workflows page as a skip
  // rather than looking like a workflow that silently stopped working.
  return [{ json: { __skipped: true, reason: decision.reason || 'not scheduled',
                    minutes_since: decision.minutes_since ?? null,
                    every_minutes: decision.every_minutes ?? null } }];
}
return $input.all();

// Returning [] stops the workflow here. Everything below this node
// is skipped, which is the entire point of the gate.
const items = $input.all();
if (items.length === 1 && items[0].json && items[0].json.__skipped) {
  console.log('skipped: ' + items[0].json.reason);
  return [];
}
return items;
